package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMlDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_seeing_first_fruit" to DuaText("ആദ്യത്തെ ഫലം കാണുക", "അല്ലാഹുവേ, ഞങ്ങളുടെ ഫലങ്ങളിൽ ഞങ്ങളെ അനുഗ്രഹിക്കേണമേ, ഞങ്ങളുടെ നഗരത്തിൽ ഞങ്ങളെ അനുഗ്രഹിക്കേണമേ, ഞങ്ങളുടെ സയിലും (അളവുകളിലും) ഞങ്ങളെ അനുഗ്രഹിക്കേണമേ.", "സീസണിലെ ആദ്യ ഫലം കണ്ടപ്പോൾ.", "ഒരാളുടെ നഗരത്തിലും ഉപജീവനത്തിലും അനുഗ്രഹത്തിനുള്ള ഒരു ദുആ."),
        "dua_good_news" to DuaText("സന്തോഷകരമായ വാർത്തകൾ", "എല്ലാ സ്തുതിയും അല്ലാഹുവിനാണ്, അവന്റെ അനുഗ്രഹത്താൽ നല്ല കാര്യങ്ങൾ പൂർത്തീകരിക്കപ്പെടുന്നു.", "ശുഭവാർത്ത ലഭിക്കുമ്പോൾ (നന്ദിയുടെ സാഷ്ടാംഗം അനുഷ്ഠിക്കുക).", "തനിക്ക് ഇഷ്ടപ്പെട്ട എന്തെങ്കിലും കണ്ടാണ് പ്രവാചകൻ ഇത് പറഞ്ഞത്."),
        "dua_looking_mirror" to DuaText("കണ്ണാടിയിൽ നോക്കുന്നു", "അല്ലാഹുവേ, നീ എൻ്റെ രൂപം ഭംഗിയാക്കിയതുപോലെ എൻ്റെ കഥാപാത്രവും ഭംഗിയാക്കുക.", "കണ്ണാടിയിൽ നോക്കുമ്പോൾ.", "നബി (സ) ഈ ദുആ ഉണ്ടാക്കി (കണ്ണാടിയുടെ പരാമർശമില്ലാതെ പോലും ഇത് സ്ഥാപിക്കപ്പെട്ടിട്ടുണ്ട്)."),
        "dua_rabbana_taqabbal" to DuaText("പ്രവൃത്തികളുടെ സ്വീകാര്യത", "ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങളിൽ നിന്ന് ഇത് സ്വീകരിക്കണമേ. തീർച്ചയായും നീ എല്ലാം കേൾക്കുന്നവനും അറിയുന്നവനും ആകുന്നു. ഞങ്ങളുടെ പശ്ചാത്താപം സ്വീകരിക്കണമേ. തീർച്ചയായും നീ പശ്ചാത്താപം സ്വീകരിക്കുന്നവനും കരുണാനിധിയുമാണ്.", "കാബാ നിർമ്മിക്കുമ്പോൾ ഇബ്രാഹിമും ഇസ്മായിലും (എ. എസ്) ആവശ്യപ്പെട്ടു.", "ഓരോ നല്ല പ്രവൃത്തിയ്ക്കും ശേഷം സ്വീകരിക്കുന്നതിനുള്ള ഒരു ദുആ."),
        "dua_muawwidhat" to DuaText("മൂന്ന് ഖുൽസ് (മുവായ്വിത്)", "പറയുകഃ അവൻ ഏകനായ അല്ലാഹുവാകുന്നു. സ്വയംപര്യാപ്തനായ അല്ലാഹുവാകുന്നു. അവൻ ജനിക്കുകയോ ജനിക്കുകയോ ചെയ്യുന്നില്ല. അവനോട് തുലനം ചെയ്യാൻ ആരുമില്ല.\n\n(സൂറത്ത് അൽ-തലാഖ്) പറയുകഃ ഞാൻ പ്രഭാതത്തിൻറെ രക്ഷിതാവിങ്കൽ അഭയം തേടുന്നു, അവൻ സൃഷ്ടിച്ചതിൻറെ തിന്മയിൽ നിന്നും, അത് നിലനില്ക്കുമ്പോൾ ഇരുട്ടിൻറെ തിന്മയിൽ നിന്നും, മുടിൽ വീശുന്നവരുടെ തിന്മയിൽ നിന്നും, അസൂയപ്പെടുമ്പോൾ അസൂയപ്പെടുന്നവരുടെ തിന്മയിൽ നിന്നും.\n\nപറയുകഃ ജിന്നുകളുടെയും മനുഷ്യരുടെയും ഇടയിൽ നിന്ന് മനുഷ്യരുടെ ഹൃദയങ്ങളിൽ നിന്ന് കിംവദന്തികൾ പരത്തുന്ന പിൻവാങ്ങുന്ന മന്ത്രിപ്പിക്കുന്നയാളുടെ തിന്മയിൽ നിന്ന് മനുഷ്യരാശിയുടെ രക്ഷിതാവായ മനുഷ്യരാശിയുടെ രാജാവായ മനുഷ്യരാശിയുടെ ദൈവത്തിൽ ഞാൻ അഭയം തേടുന്നു.", "മൂന്ന് സൂറകളും രാവിലെയും വൈകുന്നേരവും മൂന്ന് തവണ, ഉറങ്ങുന്നതിനുമുമ്പ്, കൈകളിൽ വീശുകയും ശരീരത്തിന് മുകളിൽ തുടച്ചുനീക്കുകയും ചെയ്യുക.", "രാവിലെയും വൈകുന്നേരവും മൂന്ന് തവണ അവ പാരായണം ചെയ്താൽ മതിയാകും."),
        "dua_sabr" to DuaText("ക്ഷമയ്ക്കും സ്ഥിരതയ്ക്കും", "ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങളുടെമേൽ ക്ഷമ ചൊരിയണമേ, ഞങ്ങളുടെ കാലുകൾ ഉറപ്പിക്കുകയും സത്യനിഷേധികൾക്കെതിരെ ഞങ്ങളെ സഹായിക്കുകയും ചെയ്യേണമേ.", "കഷ്ടപ്പാടുകളുടെയും ഏറ്റുമുട്ടലുകളുടെയും സമയങ്ങളിൽ.", "താലൂത്തിന്റെ സൈന്യത്തിന്റെ ദുആ."),
        "dua_rabbana_innana_amanna" to DuaText("ക്ഷമിക്കലും തീയിൽ നിന്നുള്ള സംരക്ഷണവും", "ഞങ്ങളുടെ രക്ഷിതാവേ, ഞങ്ങൾ വിശ്വസിച്ചിരിക്കുന്നു. അതിനാൽ ഞങ്ങളുടെ പാപങ്ങൾ നീ പൊറുത്തുതരേണമേ. നരകശിക്ഷയിൽ നിന്ന് ഞങ്ങളെ നീ സംരക്ഷിക്കേണമേ.", "ഖുർആൻ ദുആ.", "ദൈവഭയമുള്ളവരുടെ ഗുണങ്ങളിൽ ഒരു ദുആ പരാമർശിക്കപ്പെടുന്നു."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("നമ്മുടെ കാര്യങ്ങളിലെ മാർഗ്ഗനിർദ്ദേശം (അഷാബ് അൽ-കഹ്ഫ്)", "ഞങ്ങളുടെ കർത്താവേ, നിന്നിൽ നിന്ന് ഞങ്ങൾക്ക് കരുണ നൽകുകയും ഞങ്ങളുടെ കാര്യത്തിൽ ശരിയായ മാർഗ്ഗനിർദ്ദേശം നൽകാൻ ഞങ്ങൾക്കായി ഒരുക്കുകയും ചെയ്യേണമേ.", "ഗുഹയിലെ ആളുകളുടെ ദുആ.", "തീരുമാനങ്ങളിലും ദുഷ്കരമായ സാഹചര്യങ്ങളിലും മാർഗ്ഗനിർദ്ദേശം നൽകുക."),
        "dua_musa_faqir" to DuaText("മൂസയുടെ ദുആ (എ. എസ്)", "എൻറെ രക്ഷിതാവേ, നീ എനിക്ക് ഇറക്കിത്തരുന്ന ഏതൊരു നന്മയും എനിക്ക് തീർച്ചയായും ആവശ്യമാണ്.", "ഉപജീവനവും നന്മയും തേടുക-മദ്യാനിലെ മൂസ (എ. എസ്) യുടെ ദുആ.", "ഈ ദുആയ്ക്ക് ശേഷം അല്ലാഹു മൂസയ്ക്ക് (അ. സ.) ഒരു വീടും ജോലിയും ഭാര്യയും നൽകി."),
        "dua_ayyub" to DuaText("അയ്യൂബ് (എ. എസ്)-ൻറെ ദുആ രോഗാവസ്ഥയിൽ", "(എൻറെ രക്ഷിതാവേ,) എന്നെ ഉപദ്രവിച്ചിരിക്കുന്നു. നീ കരുണാനിധിയിൽ ഏറ്റവും കരുണാനിധിയാണ്.", "രോഗത്തിലും കഷ്ടപ്പാടിലും.", "അയ്യൂബിൻറെ (അ. സ.) കഷ്ടപ്പാടുകൾ അല്ലാഹു നീക്കി."),
        "dua_husn_khatimah" to DuaText("ഒരു മുസ്ലിമായി മരിക്കുക (യൂസഫ് എ. എസ്)", "ആകാശങ്ങളുടെയും ഭൂമിയുടെയും സ്രഷ്ടാവേ, നീ ഈ ലോകത്തും പരലോകത്തും എന്റെ രക്ഷകനാണ്. എന്നെ ഒരു മുസ്ലിമായി മരിപ്പിക്കുകയും, നീതിമാന്മാരോട് ചേർന്ന് എന്നെ സഹായിക്കുകയും ചെയ്യേണമേ.", "ഒരു നല്ല അവസാനത്തിനുള്ള ഒരു ദുആ.", "പ്രവാചകൻ യൂസഫ് (അ. സ.) യുടെ ദൂതം."),
        "dua_shaitan_hamazat" to DuaText("പിശാചിൻ്റെ ശബ്ദങ്ങളിൽ നിന്നുള്ള അഭയം", "എൻറെ രക്ഷിതാവേ, പിശാചുക്കളുടെ മന്ത്രവാദങ്ങളിൽനിന്ന് ഞാൻ അങ്ങയിൽ അഭയം തേടുന്നു. എൻറെ രക്ഷിതാവേ, അവർ എൻറെ അടുത്തേക്ക് വരാതിരിക്കുവാൻ അങ്ങയിൽ അഭയം തേടുന്നു.", "സാത്താൻ്റെ കിംവദന്തികളിൽനിന്ന് അഭയം തേടുക.", "അഭയം തേടുന്ന ഖുർആൻ ദുആ."),
        "dua_bad_character" to DuaText("മോശം സ്വഭാവത്തിൽ നിന്നുള്ള അഭയം", "അല്ലാഹുവേ, ദുർവൃത്തികളിൽ നിന്നും തിന്മകളിൽ നിന്നും തിന്മകളിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "മോശം സ്വഭാവത്തിൽ നിന്നും പ്രവൃത്തികളിൽ നിന്നും ആഗ്രഹങ്ങളിൽ നിന്നും അഭയം തേടുക.", "നബി (സ) യുടെ ഒരു അഭയം."),
        "dua_zawal_nimah" to DuaText("അനുഗ്രഹങ്ങളുടെ നഷ്ടത്തിൽ നിന്നുള്ള അഭയം", "അല്ലാഹുവേ, നിൻറെ അനുഗ്രഹങ്ങൾ നഷ്ടപ്പെടുന്നതിൽ നിന്നും, നീ നൽകിയ ക്ഷേമത്തിൻറെ മാറ്റത്തിൽ നിന്നും, നിൻറെ പെട്ടെന്നുള്ള ശിക്ഷയിൽ നിന്നും, നിൻറെ എല്ലാ അസന്തുഷ്ടിയിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "അനുഗ്രഹങ്ങൾ നഷ്ടപ്പെടുന്നതിലും പെട്ടെന്നുള്ള ദുരന്തത്തിലും നിന്ന് അഭയം തേടുക.", "നബി (സ) യുടെ ഒരു ദുആ."),
        "dua_useless_knowledge" to DuaText("പ്രയോജനമില്ലാത്ത അറിവിൽ നിന്നുള്ള അഭയം", "അല്ലാഹുവേ, പ്രയോജനപ്പെടാത്ത അറിവുകളിൽ നിന്നും ഭയപ്പെടാത്ത ഹൃദയത്തിൽ നിന്നും ഒരിക്കലും സംതൃപ്തരാകാത്ത ആത്മാവിൽ നിന്നും ഉത്തരം ലഭിക്കാത്ത ഒരു ദ്വൈവത്തിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "ഉപയോഗശൂന്യമായ അറിവുകളിൽ നിന്നും അല്ലാഹുവിനെ ഭയപ്പെടാത്ത ഹൃദയത്തിൽ നിന്നും അഭയം തേടുക.", "നബി (സ) യുടെ ഒരു അഭയം."),
        "dua_beneficial_knowledge" to DuaText("പ്രയോജനകരമായ അറിവും ഹലാൽ റിസും", "അല്ലാഹുവേ, പ്രയോജനകരമായ അറിവും ശുദ്ധമായ ഉപജീവനവും സ്വീകാര്യമായ പ്രവർത്തനങ്ങളും ഞാൻ നിന്നോടു യാചിക്കുന്നു.", "ഫജ്ർ പ്രാർത്ഥനയ്ക്ക് ശേഷം.", "ഫജ്റിൻ്റെ നമസ്കാരത്തിനുശേഷം പ്രവാചകൻ സൽഹഅലിഹ് വസ്ലം ഇത് പറഞ്ഞു."),
        "dua_leprosy_diseases" to DuaText("ഗുരുതരമായ രോഗങ്ങളിൽ നിന്നുള്ള അഭയം", "അല്ലാഹുവേ, നീല, ഭ്രാന്ത്, കുഷ്ഠം, എല്ലാ തിന്മകളും എന്നിവയിൽ നിന്ന് ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "ഗുരുതരമായ രോഗങ്ങളിൽ നിന്നുള്ള സംരക്ഷണം.", "ആരോഗ്യം സംരക്ഷിക്കുന്നതിനുള്ള ഒരു സുന്നത്ത് ദുആ."),
        "dua_fear_people" to DuaText("ശത്രുക്കളെയോ അടിച്ചമർത്തലുകളെയോ കുറിച്ചുള്ള ഭയം", "അല്ലാഹുവേ, ഞങ്ങൾ നിന്നെ അവരുടെ മുമ്പിൽ നിർത്തുകയും അവരുടെ തിന്മകളിൽ നിന്ന് നിന്നിൽ അഭയം തേടുകയും ചെയ്യുന്നു.", "ഒരു ജനതയുടെയോ വ്യക്തിയുടെയോ ദോഷം ഭയപ്പെടുമ്പോൾ.", "ഒരു ജനതയെ ഭയപ്പെട്ടപ്പോഴാണ് പ്രവാചകൻ ഇത് പറഞ്ഞത്."),
        "dua_shirk_protection" to DuaText("മറഞ്ഞിരിക്കുന്ന ഷിർക്കിൽ നിന്നുള്ള സംരക്ഷണം", "അല്ലാഹുവേ, ഞാൻ നിന്നോട് എന്തെങ്കിലും അറിയാമെങ്കിൽ പങ്കുചേർക്കുന്നതിൽ നിന്ന് നിന്നിൽ അഭയം തേടുന്നു. ഞാൻ അറിയാതെ ചെയ്യുന്നതിന് നിന്നോട് പാപമോചനം തേടുന്നു.", "കാണിക്കുന്നതിൽ നിന്നും മറഞ്ഞിരിക്കുന്ന ഷിർക്കിൽ നിന്നും സുരക്ഷിതമായി ഇരിക്കാൻ.", "ഉറുമ്പുകളുടെ ഇഴയുന്നതിനേക്കാൾ മറഞ്ഞിരിക്കുന്ന ഷിർക്ക് കൂടുതൽ മറഞ്ഞിരിക്കുന്നു."),
        "dua_rain" to DuaText("മഴ പെയ്യുമ്പോൾ", "അല്ലാഹുവേ, ഗുണകരമായ ഒരു മഴ (അയയ്ക്കുക).", "മഴ പെയ്യുമ്പോൾ.", "ദുആകൾ സ്വീകരിക്കപ്പെടുന്ന സമയമാണ് മഴ."),
        "dua_after_rain" to DuaText("മഴയ്ക്ക് ശേഷം", "അല്ലാഹുവിൻറെ അനുഗ്രഹവും അവൻറെ കാരുണ്യവും കൊണ്ടാണ് ഞങ്ങൾക്ക് മഴ ലഭിച്ചത്.", "മഴയ്ക്ക് ശേഷം.", "ഇത് പറയുന്നവൻ അല്ലാഹുവിൽ വിശ്വസിക്കുന്നയാളാണ്."),
        "dua_istisqa" to DuaText("മഴ ആവശ്യപ്പെടുക (ഇസ്തിസ്ക)", "അല്ലാഹുവേ, ഞങ്ങൾക്ക് മൂന്ന് തവണ മഴ നൽകേണമേ.", "മഴയില്ലാത്തപ്പോൾ.", "വെള്ളിയാഴ്ചത്തെ പ്രഭാഷണത്തിൽ പ്രവാചകൻ സൽഹഅലിഹ് വസ്ലം ഈ ദുആ നടത്തുകയും മഴ പെയ്തു."),
        "dua_heavy_rain" to DuaText("അമിതമായ മഴ", "അല്ലാഹുവേ, അത് നമ്മുടെ മേൽ വീഴാതെ നമുക്ക് ചുറ്റും വീഴാൻ അനുവദിക്കുക.", "മഴ കൂടുതലായിരിക്കുമ്പോൾ.", "പ്രവാചകൻറെ ദ്വൈവൃത്തത്തിലൂടെ മേഘങ്ങൾ നീങ്ങി."),
        "dua_wind" to DuaText("കാറ്റ് വീശുമ്പോൾ", "അല്ലാഹുവേ, അതിൻറെ നന്മയും അതിൻറെ ഉള്ളിലെ നന്മയും അതിൻറെ കൂടെ അയച്ചതിൻറെ നന്മയും ഞാൻ നിന്നോടു ചോദിക്കുന്നു. അതിൻറെ തിന്മയിൽ നിന്നും അതിൻറെ ഉള്ളിലെ തിന്മയിൽ നിന്നും അത് അയച്ചതിൻറെ തിന്മയിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "ശക്തമായ കാറ്റോ കൊടുങ്കാറ്റോ വീശുമ്പോൾ.", "പ്രവാചകൻ സൽഹുല്ലാഹ്ലാഹു സൽമാൻ കൊടുങ്കാറ്റുകളിൽ ഈ ദുആ നിർമ്മിച്ചു."),
        "dua_thunder" to DuaText("ഇടിമിന്നൽ കേൾക്കുന്നു", "ഇടിമുഴക്കം തൻ്റെ സ്തുതിയോടെ മഹത്വപ്പെടുത്തുന്നവനും അവനെ ഭയപ്പെടുന്ന ദൂതന്മാർക്കും മഹത്വം.", "ഇടിമുഴക്കം കേൾക്കുമ്പോൾ-അബ്ദുല്ല ഇബ്നു അസ്-സുബൈർ (റ) യുടെ ആചാരം.", "സൂറ അർ-റാദിൽ നിന്ന് എടുത്തതാണ് (13:13)."),
        "dua_new_moon" to DuaText("അമാവാസി കാണുന്നത്", "അല്ലാഹുവേ, അനുഗ്രഹവും വിശ്വാസവും സുരക്ഷിതത്വവും ഇസ്ലാമും കൊണ്ട് ഈ ചന്ദ്രൻ ഞങ്ങളുടെ മേൽ ഉദിക്കട്ടെ. (ചന്ദ്രനേ,) എൻറെ രക്ഷിതാവും നിൻറെ രക്ഷിതാവുമായ അല്ലാഹുവാണ്.", "അമാവാസി കണ്ടപ്പോൾ.", "എല്ലാ പുതിയ മാസത്തിലും സുന്നത്ത് ദുആ."),
        "dua_janaza_adult" to DuaText("ജനസാ പ്രാർത്ഥന (മുതിർന്നവർ)", "അല്ലാഹുവേ, ഞങ്ങളുടെ ജീവിച്ചിരിക്കുന്നവർക്കും മരിച്ചവർക്കും, സന്നിഹിതരും ഇല്ലാതിരിക്കുന്നവർക്കും, ഞങ്ങളുടെ ചെറുപ്പക്കാർക്കും, ഞങ്ങളുടെ മുതിർന്നവർക്കും, ഞങ്ങളുടെ പുരുഷന്മാർക്കും സ്ത്രീകൾക്കും നീ മാപ്പ് നൽകണേ. അല്ലാഹുവേ, ഞങ്ങളിൽ ആരെയെങ്കിലും നീ ജീവിപ്പിച്ചുവെച്ചാൽ അവനെ ഇസ്ലാമിൽ ജീവിപ്പിച്ചുകൊൾക. ഞങ്ങളിൽ ആരെയെങ്കിലും നീ മരിപ്പിച്ചാലും അവനെ വിശ്വാസത്താൽ മരിപ്പിക്കേണമേ.", "ശവസംസ്കാര പ്രാർത്ഥനയുടെ മൂന്നാമത്തെ തക്ബീറിന് ശേഷം.", "മരിച്ചുപോയ ഒരു മുതിർന്നയാൾക്കുള്ള സുന്നത്ത് ദുആ."),
        "dua_janaza_child" to DuaText("ജനസാ പ്രാർത്ഥന (കുട്ടി)", "അല്ലാഹുവേ, അവനെ ഞങ്ങൾക്ക് മുൻഗാമിയാക്കുക. അവനെ ഞങ്ങൾക്ക് പ്രതിഫലവും നിധിയും ആക്കുക. ശുപാർശ സ്വീകരിക്കപ്പെടുന്നവനായി അവനെ ഞങ്ങൾക്ക് ശുപാർശ ചെയ്യുന്നവനായി ആക്കുക.", "ഒരു കുട്ടിയുടെ ശവസംസ്കാര പ്രാർത്ഥനയിൽ (ഒരു പെൺകുട്ടിക്ക്'ഇജൽഹാ'എന്ന് പറയുക).", "ഹനഫികൾ അനുഷ്ഠിച്ചിരുന്ന സുന്നഹ് ദുആ."),
        "dua_mayyit_awf" to DuaText("മരിച്ചവർക്കുള്ള വിശദമായ ദുവാ", "അല്ലാഹുവേ, അവനോട് ക്ഷമിക്കണമേ, അവനോട് കരുണ കാണിക്കണമേ, അവന് ക്ഷേമം നൽകണമേ, അവനോട് ക്ഷമിക്കണമേ. അവന്റെ സ്വീകരണത്തെ മാന്യമാക്കുകയും ശവകുടീരം വിശാലമാക്കുകയും വെള്ളവും മഞ്ഞും ആലിപ്പഴവും കൊണ്ട് കഴുകുകയും, ഒരു വെളുത്ത വസ്ത്രം അഴുക്കുകൊണ്ട് ശുദ്ധീകരിക്കപ്പെടുന്നതുപോലെ പാപങ്ങളിൽ നിന്ന് അവനെ ശുദ്ധീകരിക്കുകയും ചെയ്യുക.", "ശവസംസ്കാര പ്രാർത്ഥനയിൽ അല്ലെങ്കിൽ മരിച്ചവർക്ക് വേണ്ടി.", "അവ്ഫ് ഇബ്നു മാലിക് (റ) മരിച്ചുപോയ ആ വ്യക്തിയായിരിക്കണമെന്ന് ആഗ്രഹിച്ചു."),
        "dua_visiting_graves" to DuaText("ശവകുടീരങ്ങൾ സന്ദർശിക്കുന്നു", "ഈ വീടുകളിൽ വസിക്കുന്ന വിശ്വാസികളേ, നിങ്ങൾക്ക് സമാധാനം നേരുന്നു. അല്ലാഹു ഉദ്ദേശിക്കുന്നുവെങ്കിൽ ഞങ്ങളും നിങ്ങളോടൊപ്പം ചേരും. ഞങ്ങൾക്കും നിങ്ങൾക്കും വേണ്ടി ഞാൻ അല്ലാഹുവോട് ക്ഷേമം തേടുന്നു.", "ശ്മശാനത്തിൽ പ്രവേശിക്കുമ്പോൾ.", "ശവകുടീരങ്ങൾ സന്ദർശിക്കുന്നത് ഒരാളുടെ മരണത്തെയും പരലോകത്തെയും ഓർമ്മിപ്പിക്കുന്നു."),
        "dua_closing_eyes" to DuaText("മരിച്ചവരുടെ കണ്ണുകൾ അടച്ചപ്പോൾ", "അല്ലാഹുവേ, നീ പൊറുത്തുതരേണമേ. നേർവഴിയുള്ളവരിൽ നിന്ന് അവൻറെ സ്ഥാനം ഉയർത്തണമേ. അവൻ ഉപേക്ഷിക്കുന്നവരിൽ നിന്ന് അവൻറെ പിൻഗാമിയാകണമേ. ലോകരക്ഷിതാവേ, നീ ഞങ്ങളോടും അവനോടും പൊറുത്തുതരേണമേ. അവൻറെ ശവകുടീരം വിശാലമാക്കുകയും അതിൽ പ്രകാശം നിറയ്ക്കുകയും ചെയ്യേണമേ.", "മരിച്ചയാളുടെ കണ്ണുകൾ അടയ്ക്കുമ്പോൾ (അദ്ദേഹത്തിന്റെ പേര് പരാമർശിക്കുമ്പോൾ).", "നബി (സ) യുടേത് അബു സലമയ്ക്ക് വേണ്ടിയുള്ളതാണ്."),
        "dua_condolence" to DuaText("അനുശോചനം (ത'സിയാഹ്)", "തീർച്ചയായും അവൻ എടുത്തതെല്ലാം അല്ലാഹുവിന്നാകുന്നു. അവൻ നൽകിയത് അവന്നാകുന്നു. അവൻറെ പക്കലുള്ളതെല്ലാം ഒരു നിശ്ചിത കാലയളവുള്ളതാണ്. അതിനാൽ നിങ്ങൾ ക്ഷമയോടെ കാത്തിരിക്കുകയും പ്രതിഫലം പ്രതീക്ഷിക്കുകയും ചെയ്യുക.", "ഒരു മരണശേഷം ഒരു കുടുംബത്തിന് അനുശോചനം അറിയിക്കുന്നു.", "നബി (സ) തന്റെ മകൾക്ക് ഈ സന്ദേശം അയച്ചു."),
        "dua_placing_in_grave" to DuaText("മരിച്ചവരെ ശവകുടീരത്തിൽ പാർപ്പിക്കുക", "അല്ലാഹുവിൻ്റെ നാമത്തിലും അല്ലാഹുവിൻ്റെ ദൂതനെ വഴിയും.", "മരിച്ചയാളെ ശവകുടീരത്തിലേക്ക് താഴെയിറക്കുമ്പോൾ.", "ശവസംസ്കാരത്തിൻ്റെ സുന്നത്ത് ദുആ."),
        "dua_sneezing" to DuaText("തുമ്മൽ", "എല്ലാ സ്തുതിയും അല്ലാഹുവിനാണ്.-അല്ലാഹു നിങ്ങളോട് കരുണ കാണിക്കട്ടെ.-അല്ലാഹു നിങ്ങളെ നയിക്കുകയും നിങ്ങളുടെ കാര്യങ്ങൾ ശരിയായി നടത്തുകയും ചെയ്യട്ടെ.", "തുമ്മുമ്പോൾ ശ്രോതാക്കൾ'യർഹമുകല്ലാഹ്'എന്ന് പറയുകയും, തുമ്മുന്നവർ മറുപടി നൽകുകയും ചെയ്യുന്നു.", "ഇത് മറ്റൊരു മുസ്ലിമിൻ്റെ മേൽ ഒരു മുസ്ലിമിൻ്റെ അവകാശങ്ങളിലൊന്നാണ്."),
        "dua_toilet_enter" to DuaText("ടോയ്ലറ്റിൽ പ്രവേശിക്കുന്നു", "അല്ലാഹുവിൻറെ നാമത്തിൽ. അല്ലാഹുവേ, അശുദ്ധനായ ജിന്നുകളിൽനിന്ന് ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "ടോയ്ലറ്റിൽ കയറുന്നതിന് മുമ്പ് ഇടത് കാൽ വച്ച്.", "ജിന്നുകൾക്കും വ്യക്തികൾക്കും ഇടയിലുള്ള ഒരു സ്ക്രീനായി ബിസ്മില്ല മാറുന്നു."),
        "dua_toilet_exit" to DuaText("ടോയ്ലറ്റ് വിടുക", "(അല്ലാഹുവേ,) ഞാൻ നിന്നോട് പാപമോചനം തേടുന്നു.", "ടോയ്ലറ്റിൽ നിന്ന് വലത് കാൽ കൊണ്ട് പുറത്തിറങ്ങുമ്പോൾ.", "പ്രവാചകൻ സൽഹുല്ലാഹ്ലാഹു സൽമാൻ ശൌചാലയത്തിൽ നിന്ന് ഇറങ്ങിയപ്പോഴാണ് ഇത് പറഞ്ഞത്."),
        "dua_thanking" to DuaText("ആരോടെങ്കിലും നന്ദി പറയുക", "അല്ലാഹു നിങ്ങൾക്ക് നന്മ നൽകട്ടെ.", "ആരെങ്കിലും നിങ്ങൾക്ക് ഒരു ഉപകാരം ചെയ്യുമ്പോൾ.", "ഇത് പറയുന്നവർക്ക് അദ്ദേഹം പൂർണ്ണമായും നന്ദി പറഞ്ഞു."),
        "dua_love_for_allah" to DuaText("'ഞാൻ നിന്നെ അല്ലാഹുവിന് വേണ്ടി സ്നേഹിക്കുന്നു'എന്ന് ആരെങ്കിലും പറയുമ്പോൾ", "നിങ്ങൾ എന്നെ സ്നേഹിക്കുന്ന അല്ലാഹുവിന് നിങ്ങളെ സ്നേഹിക്കട്ടെ.", "'അല്ലാഹുവിൻ്റെ പേരിൽ ഞാൻ നിന്നെ സ്നേഹിക്കുന്നു'എന്ന് ആരെങ്കിലും പറയുമ്പോൾ.", "അല്ലാഹുവോടുള്ള സ്നേഹത്തിന് സുന്നത്ത് ഉത്തരം നൽകുന്നു."),
        "dua_seeing_muslim_smile" to DuaText("അഭിവാദ്യം (സലാം)", "നിങ്ങൾക്ക് സമാധാനം നേരുന്നു, അല്ലാഹുവിൻറെ കാരുണ്യവും അവൻറെ അനുഗ്രഹങ്ങളും നേരുന്നു.", "ഒരു മുസ്ലിമിനെ കണ്ടുമുട്ടുമ്പോൾ.", "സമ്പൂർണ്ണ സലാം പറഞ്ഞാൽ മുപ്പത് നല്ല പ്രവൃത്തികൾ ലഭിക്കും."),
        "dua_dressing" to DuaText("വസ്ത്രം ധരിക്കുക", "എന്നെ ഇത് ധരിപ്പിക്കുകയും എന്റെ ഭാഗത്തുനിന്നുള്ള ശക്തിയോ അധികാരമോ ഇല്ലാതെ എനിക്ക് അത് നൽകുകയും ചെയ്ത അല്ലാഹുവിന് എല്ലാ സ്തുതിയും.", "വസ്ത്രം ധരിക്കുമ്പോൾ.", "മുൻകാല പാപങ്ങൾക്കുള്ള ക്ഷമയുടെ സന്തോഷവാർത്ത."),
    )
}
